import { describe, expect, it } from 'vitest';
import { execFileSync, spawnSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { parsePDF, getPageContentBytes } from '../parser/parser';
import { PDFRef, PDFStream } from '../types';
import { saveOptimized, saveQuick } from '../writer/save-pipeline';

/** Hand-built xref and indirect length; the PDF payload is not generated by the parser under test. */
function fixture(data: Uint8Array, lengthBody = String(data.length), extraBody?: string, omitLength = false): Uint8Array {
  const encoder = new TextEncoder();
  const chunks: Uint8Array[] = [];
  let size = 0;
  const append = (bytes: Uint8Array) => { chunks.push(bytes); size += bytes.length; };
  const text = (value: string) => append(encoder.encode(value));
  const offsets: number[] = [0];
  text('%PDF-1.7\n');
  const object = (number: number, value: string) => {
    offsets[number] = size;
    text(`${number} 0 obj\n${value}\nendobj\n`);
  };
  object(1, '<< /Type /Catalog /Pages 2 0 R >>');
  object(2, '<< /Type /Pages /Kids [3 0 R] /Count 1 >>');
  object(3, '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 200 200] /Resources << >> /Contents 4 0 R >>');
  offsets[4] = size;
  text(`4 0 obj\n<< ${omitLength ? '' : '/Length 5 0 R'} >>\nstream\n`);
  append(data);
  text('\nendstream\nendobj\n');
  object(5, lengthBody);
  if (extraBody !== undefined) object(6, extraBody);
  const xref = size;
  const count = extraBody === undefined ? 6 : 7;
  text(`xref\n0 ${count}\n0000000000 65535 f \n`);
  for (let i = 1; i < count; i++) text(`${String(offsets[i]).padStart(10, '0')} 00000 n \n`);
  text(`trailer\n<< /Size ${count} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`);
  const bytes = new Uint8Array(size);
  let offset = 0;
  for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.length; }
  return bytes;
}

function compressedLengthFixture(data: Uint8Array, cyclic = false): Uint8Array {
  const encoder = new TextEncoder(), chunks: Uint8Array[] = [], offsets: number[] = [0];
  let size = 0;
  const append = (value: Uint8Array) => { chunks.push(value); size += value.length; };
  const text = (value: string) => append(encoder.encode(value));
  const object = (id: number, value: string) => { offsets[id] = size; text(`${id} 0 obj\n${value}\nendobj\n`); };
  text('%PDF-1.7\n');
  object(1, '<< /Type /Catalog /Pages 2 0 R >>');
  object(2, '<< /Type /Pages /Kids [3 0 R] /Count 1 >>');
  object(3, '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 200 200] /Resources << >> /Contents 4 0 R >>');
  offsets[4] = size;
  text('4 0 obj\n<< /Length 5 0 R >>\nstream\n'); append(data); text('\nendstream\nendobj\n');
  const objectStream = encoder.encode(`5 0 ${data.length}`);
  offsets[6] = size;
  text(`6 0 obj\n<< /Type /ObjStm /N 1 /First 4 /Length ${cyclic ? '5 0 R' : objectStream.length} >>\nstream\n`);
  append(objectStream); text('\nendstream\nendobj\n');
  offsets[7] = size;
  const table = new Uint8Array(8 * 7), view = new DataView(table.buffer);
  for (let n = 0; n < 8; n++) {
    const pos = n * 7;
    view.setUint8(pos, n === 0 ? 0 : n === 5 ? 2 : 1);
    view.setUint32(pos + 1, n === 0 ? 0 : n === 5 ? 6 : offsets[n], false);
    view.setUint16(pos + 5, n === 0 ? 65535 : 0, false);
  }
  text(`7 0 obj\n<< /Type /XRef /Size 8 /Root 1 0 R /W [1 4 2] /Length ${table.length} >>\nstream\n`);
  append(table); text(`\nendstream\nendobj\nstartxref\n${offsets[7]}\n%%EOF\n`);
  const result = new Uint8Array(size);
  let at = 0;
  for (const chunk of chunks) { result.set(chunk, at); at += chunk.length; }
  return result;
}

const payload = new TextEncoder().encode('q\n% endstream is inside a stream comment\n0 0 1 rg\n20 20 50 50 re f\nQ\r\n\n');

describe('indirect stream lengths', () => {
  it.each(['quick', 'optimized'] as const)('preserves exact bytes through parse and %s save', async mode => {
    const doc = await parsePDF(fixture(payload));
    const ref = doc.pages[0].contentRefs[0];
    const stream = doc.objects.get(ref.toKey());
    expect(stream).toBeInstanceOf(PDFStream);
    expect((stream as PDFStream).rawBytes).toEqual(payload);
    const saved = mode === 'quick' ? await saveQuick(doc) : await saveOptimized(doc);
    const reopened = await parsePDF(saved);
    expect(getPageContentBytes(reopened.pages[0], reopened.objects)).toEqual(payload);
  });

  it('rejects an unresolved length without yielding a truncated stream', async () => {
    await expect(parsePDF(fixture(payload, '42 0 R'))).rejects.toThrow(/length/i);
  });

  it('rejects a cyclic indirect length without yielding a truncated stream', async () => {
    await expect(parsePDF(fixture(payload, '5 0 R'))).rejects.toThrow(/length/i);
  });

  it('retains indirect length references when object stream filters are deferred', async () => {
    const doc = await parsePDF(fixture(payload), { deferEncryptedFilters: true });
    expect(doc.objects.get('4_0')).toBeInstanceOf(PDFStream);
    const stream = doc.objects.get('4_0') as PDFStream;
    expect(stream.rawBytes).toEqual(payload);
    expect(stream.dict.get('Length')).not.toBeInstanceOf(PDFRef);
  });

  it('resolves chains of indirect references before slicing bytes', async () => {
    const doc = await parsePDF(fixture(payload, '6 0 R', String(payload.length)));
    expect(getPageContentBytes(doc.pages[0], doc.objects)).toEqual(payload);
    const reopened = await parsePDF(await saveQuick(doc));
    expect(getPageContentBytes(reopened.pages[0], reopened.objects)).toEqual(payload);
  });

  it('resolves a length stored in an object stream before decoding the affected stream', async () => {
    const doc = await parsePDF(compressedLengthFixture(payload));
    expect(getPageContentBytes(doc.pages[0], doc.objects)).toEqual(payload);
    const reopened = await parsePDF(await saveQuick(doc));
    expect(getPageContentBytes(reopened.pages[0], reopened.objects)).toEqual(payload);
  });

  it('rejects an object-stream length that depends on its own unread object stream', async () => {
    await expect(parsePDF(compressedLengthFixture(payload, true))).rejects.toThrow(/stream length/i);
  });

  it('trims only one separator EOL in fallback recovery', async () => {
    const data = new TextEncoder().encode('q\nQ\r\n\n');
    const doc = await parsePDF(fixture(data, String(data.length), undefined, true));
    expect(getPageContentBytes(doc.pages[0], doc.objects)).toEqual(data);
  });

  it('preserves arbitrary binary bytes including embedded delimiters and trailing CR/LF', async () => {
    const prefix = new Uint8Array([0, 255, 254, 13, 10, 2]);
    const embedded = new TextEncoder().encode('endstream');
    const data = new Uint8Array([...prefix, ...embedded, 0, 128, 13, 10, 10]);
    const doc = await parsePDF(fixture(data));
    expect((doc.objects.get('4_0') as PDFStream).rawBytes).toEqual(data);
    const reopened = await parsePDF(await saveOptimized(doc));
    expect((reopened.objects.get(reopened.pages[0].contentRefs[0].toKey()) as PDFStream).rawBytes).toEqual(data);
  });

  it('rejects a resolved length that does not terminate at endstream', async () => {
    await expect(parsePDF(fixture(payload, String(payload.length - 2)))).rejects.toThrow(/stream length/i);
    await expect(parsePDF(fixture(payload, '999999'))).rejects.toThrow(/stream length/i);
  });

  const poppler = spawnSync('pdftoppm', ['-v'], { stdio: 'ignore' }).status === 0;
  it.skipIf(!poppler)('renders content after the embedded marker before and after saving in Poppler', async () => {
    const source = fixture(payload), doc = await parsePDF(source), saved = await saveQuick(doc);
    const dir = mkdtempSync(join(tmpdir(), 'paperloom-indirect-stream-'));
    try {
      for (const [name, bytes] of [['source', source], ['saved', saved]] as const) {
        const path = join(dir, `${name}.pdf`), prefix = join(dir, name);
        writeFileSync(path, bytes);
        execFileSync('pdftoppm', ['-singlefile', '-r', '72', '-f', '1', '-l', '1', path, prefix]);
        const ppm = readFileSync(`${prefix}.ppm`);
        const header = /^P6\s+200\s+200\s+255\s/.exec(ppm.toString('latin1', 0, 64));
        if (!header) throw new Error('Unexpected PPM output');
        const position = header[0].length + ((199 - 40) * 200 + 40) * 3;
        expect([...ppm.subarray(position, position + 3)]).toEqual([0, 0, 255]);
      }
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });
});
